using System.Collections.Frozen;
using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// High-throughput product catalog optimized for bulk lookups.
/// Uses FrozenDictionary for faster reads, a reverse index for category queries,
/// and SIMD-vectorized summation for batch price calculations.
/// </summary>
public sealed class ProductCatalog
{
    private FrozenDictionary<string, string> _categories = FrozenDictionary<string, string>.Empty;
    private FrozenDictionary<string, int> _priceIndex = FrozenDictionary<string, int>.Empty;
    private FrozenDictionary<string, string[]> _categoryToProducts = FrozenDictionary<string, string[]>.Empty;
    private double[] _prices = [];

    public void Load(IEnumerable<(string Code, string Category, decimal Price)> products)
    {
        var categories = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var priceList = new List<double>();
        var priceIndex = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var reverseIndex = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);

        foreach (var (code, category, price) in products)
        {
            categories[code] = category;
            priceIndex[code] = priceList.Count;
            priceList.Add((double)price);

            if (!reverseIndex.TryGetValue(category, out var list))
            {
                list = [];
                reverseIndex[category] = list;
            }
            list.Add(code);
        }

        _categories = categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _priceIndex = priceIndex.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _prices = priceList.ToArray();
        _categoryToProducts = reverseIndex.ToDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase
        ).ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Computes total price using SIMD-vectorized summation over a contiguous price array.
    /// Resolves codes to array indices, then sums the corresponding prices with Vector&lt;double&gt;.
    /// </summary>
    public double GetTotalPrice(ReadOnlySpan<string> codes)
    {
        // Resolve codes to indices and gather prices into a contiguous buffer for vectorization
        int count = codes.Length;
        Span<double> resolved = count <= 256
            ? stackalloc double[count]
            : new double[count];

        int resolvedCount = 0;
        for (int i = 0; i < count; i++)
        {
            if (_priceIndex.TryGetValue(codes[i], out int idx))
                resolved[resolvedCount++] = _prices[idx];
        }

        return SimdSum(resolved[..resolvedCount]);
    }

    /// <summary>
    /// Overload accepting IEnumerable for backward compatibility.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        var array = codes as string[] ?? codes.ToArray();
        return GetTotalPrice(array.AsSpan());
    }

    public ReadOnlySpan<string> GetProductsByCategory(string category)
        => _categoryToProducts.TryGetValue(category, out var products)
            ? products.AsSpan()
            : ReadOnlySpan<string>.Empty;

    private static double SimdSum(ReadOnlySpan<double> values)
    {
        double sum = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<double>.Count)
        {
            var vectors = MemoryMarshal.Cast<double, Vector<double>>(values);
            var accum = Vector<double>.Zero;

            for (int i = 0; i < vectors.Length; i++)
                accum += vectors[i];

            sum = Vector.Sum(accum);

            // Handle remaining elements not covered by full vectors
            int processed = vectors.Length * Vector<double>.Count;
            for (int i = processed; i < values.Length; i++)
                sum += values[i];
        }
        else
        {
            for (int i = 0; i < values.Length; i++)
                sum += values[i];
        }

        return sum;
    }
}

